window.NOTES={"version":70,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":32,"chapter":1,"section":"1.1","type":"判断","topic":"信息与数据","title":"数据是信息的符号化表示和载体","trigger":"真题反复考查信息、数据、符号与意义之间的标准关系。","conclusion":"数据是信息的符号化表示，是信息记录、传输和处理的载体；信息是数据经过解释后表达的意义。","points":["同一数据在不同语境中可能表达不同信息。","文字、数字、图像和声音等都可编码为数据。","介质承载数据，数据承载可被解释的信息。","教学示例：温度传感器采集读数，程序计算日均值，数据库保存历史，网络把预警传给值班人员。采集得到数据，处理产生可解释结果，存储便于以后使用，传递使信息到达需要它的人。","信息社会广泛依靠信息与通信技术进行生产、服务、学习和协作；关注的不只是拥有电脑，还包括人们能否获取、理解、利用与共享信息。","在线教育和远程协作可减少时间与距离限制；接入条件、设备和数字技能差异又可能形成数字鸿沟。评价应用既看效率，也看可达性和使用者能力。","不同的数据符号也可能表达同一信息。例如同一气温可以用数值和文字描述；比较时先分别看符号形式和被解释的意义。这与“同一数据在不同语境中可能表达不同信息”并不矛盾。","课堂将信息技术视为获取、处理、存储和传递信息资源的综合技术，并按语言、文字、造纸与印刷、电报电话、电子计算机与现代通信网络概括五次信息技术革命。这是信息技术的教学划分；计算机四代按主要电子元件划分，不能将两套顺序混用。","教学示例：同一条停课通知可通过纸质告示和群消息传给多人，说明信息表达依赖载体，也能够传递、共享；传给别人并不意味着原持有者就失去所知内容。信息的使用价值还与对象、时间和用途有关：昨日的停课通知不能直接决定今天是否上课，却仍可作为历史记录。这里体现了载体依附、传递共享、时效和价值等性质；时效性不等于过期后对所有用途都毫无价值。收到消息还要核查来源与内容，传播次数多不等于真实。"],"boundary":"不要把信息与数据完全等同，也不要把载体关系写反。","id":"y2025q23","sources":[{"year":2023,"q":32,"type":"判断"},{"year":2025,"q":23,"type":"多选"}],"keys":["2023-32","2025-23"],"related":[{"id":"y2025q2","label":"字符编码、汉字机内码、字形与全角半角要分清","reason":"字符编码说明文字怎样表示为数据；字符身份与显示字形还要继续区分。"},{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"图像把视觉信息编码为像素数据，可把抽象的载体关系落实到颜色深度。"}],"pointGroups":[{"title":"信息、数据与介质的关系","indices":[0,1,2,6]},{"title":"信息的性质与使用价值","indices":[8]},{"title":"信息技术的含义、发展与处理过程","indices":[7,3]},{"title":"信息社会与数字鸿沟","indices":[4,5]}],"pointPresentation":{"0":{"title":"数据需要语境解释","navigationLabel":"数据需要语境解释"},"1":{"title":"数据的表现形式","navigationLabel":"数据的表现形式"},"2":{"title":"介质、数据与信息的载体关系","navigationLabel":"介质、数据与信息的载体关系"},"3":{"title":"采集、处理、存储与传递","navigationLabel":"采集、处理、存储与传递"},"4":{"title":"信息社会的关注点","navigationLabel":"信息社会的关注点"},"5":{"title":"效率与数字鸿沟","navigationLabel":"效率与数字鸿沟"},"6":{"title":"不同数据也能表达同一信息","navigationLabel":"不同数据也能表达同一信息"},"7":{"title":"信息技术的五次发展与计算机四代","navigationLabel":"信息技术的五次发展与计算机四代"},"8":{"title":"从情景理解信息的性质与使用价值","navigationLabel":"从情景理解信息的性质与使用价值","blocks":[{"label":"载体与共享情景"},{"label":"时效与使用价值","from":"信息的使用价值"},{"label":"核查真伪","from":"收到消息还要"}]}}},{"q":29,"chapter":1,"section":"1.1","type":"多选","topic":"自主可控","title":"自主可控关注核心能力，也必须遵循安全规范","trigger":"真题从技术引进、国产化和数据库考查自主可控、安全与供应链。","conclusion":"自主可控要看核心技术、知识产权、供应链和维护生态；开放学习与自主创新可并行，国产化也不能跳过安全评估。","points":["关键技术应具备理解、修改和持续演进能力。","权利边界、替代能力和维护生态决定能否长期运行。","自主研发不是拒绝开放标准与国际协作。","北斗卫星导航系统是我国自主建设、独立运行的卫星导航系统，是理解自主可控的具体实例。","国产计算机涉及处理器、操作系统和应用软件等多个层次。先区分职责：处理器执行指令，操作系统管理资源并为应用提供服务，应用软件完成具体任务。例如龙芯、飞腾属于处理器平台，统信UOS属于操作系统；以统信桌面操作系统专业版V20为例，它支持龙芯、飞腾等国产CPU平台。理解国产计算机，要同时看这些软硬件能否协同工作，不能只记整机品牌。","国产化替代还涉及应用软件与外设驱动的适配：原有业务软件、浏览器插件和打印机等外设可能需要迁移或改造。采用国产处理器或操作系统，不能直接推出原有全部软件与外设都能无需适配地运行。具体兼容范围要核对产品版本和适配说明。"],"boundary":"自主可控不是只看产地标签，也不能把引进技术等同于已经掌握核心能力。","id":"y2026q18","sources":[{"year":2024,"q":29,"type":"多选"},{"year":2025,"q":15,"type":"单选"},{"year":2026,"q":18,"type":"单选"}],"keys":["2024-29","2025-15","2026-18"],"related":[{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"自主研发与引进技术都要遵守授权和署名边界，拥有产品不等于拥有全部技术权利。"}],"pointPresentation":{"4":{"title":"国产处理器、操作系统与应用的层次","navigationLabel":"国产处理器、操作系统与应用的层次","blocks":[{"label":"先认软硬件层次"},{"label":"明确版本的产品实例","from":"例如龙芯"}]},"5":{"title":"国产化迁移与兼容适配","navigationLabel":"国产化迁移与兼容适配"}},"pointGroups":[{"title":"自主可控的核心能力","indices":[0,1,2]},{"title":"国产软硬件与兼容适配","indices":[4,5]},{"title":"自主建设的其他实例","indices":[3]}]},{"q":1,"chapter":1,"section":"1.2","type":"单选","topic":"计算机发展","title":"电子管、晶体管与集成电路标志主要代际","trigger":"真题从ENIAC和代表元件反复考查电子计算机代际。","conclusion":"第一代以电子管为主，第二代以晶体管为主，第三代以中小规模集成电路为主，第四代以大规模和超大规模集成电路为主。","points":["ENIAC属于早期第一代电子管计算机。","继电器主要属于机电式计算阶段。","集成度提升推动体积、功耗、可靠性和性能变化。","ENIAC采用电子管，主要使用十进制；不能把它与后来经典存储程序计算机的二进制结构混同。","ENIAC于1946年在美国宾夕法尼亚大学公开，最初通过接线与开关为具体问题设置运算过程，不能把最初的机器说成已经采用现代存储程序方式。后来曾改造其程序存放和执行方式，因此“最初没有”不能扩大为“始终没有”。","企业发展还要看业务变化：IBM于1981年推出IBM PC，后来其个人电脑业务利润下降，2005年将PC业务出售给联想，并向软件和服务调整业务重心。这是企业转型的案例，出售某项业务不等于整家公司倒闭，也不能作为计算机代际划分依据。"],"boundary":"代际判断看主要电子元件，不以机器体积、运行速度或是否联网作为划分依据。","id":"y2025q21","sources":[{"year":2023,"q":1,"type":"单选"},{"year":2024,"q":21,"type":"多选"},{"year":2025,"q":21,"type":"多选"},{"year":2021,"q":1,"type":"单选","page":1}],"keys":["2023-1","2024-21","2025-21","2021-1"],"related":[{"id":"y2026q1","label":"计算机发展不是简单的“越大越快”","reason":"先按主要电子元件划分代际，再理解集成度如何推动体积和性能变化。"},{"id":"merged-1","label":"冯·诺依曼结构与存储程序原理","reason":"ENIAC的十进制特点不能直接套入经典存储程序模型，应分开比较历史机器与体系结构。"}],"pointPresentation":{"0":{"title":"ENIAC的代际","navigationLabel":"ENIAC的代际"},"1":{"title":"继电器与电子管","navigationLabel":"继电器与电子管"},"2":{"title":"集成度与性能变化","navigationLabel":"集成度与性能变化"},"3":{"title":"ENIAC十进制与后来的二进制结构","navigationLabel":"ENIAC十进制与后来的二进制结构"},"4":{"title":"最初的ENIAC与后来的改造","navigationLabel":"最初的ENIAC与后来的改造"},"5":{"title":"IBM个人电脑业务的兴起与转型","navigationLabel":"IBM个人电脑业务的兴起与转型"}},"pointGroups":[{"title":"代际依据与ENIAC","indices":[0,1,2,3]},{"title":"历史条件与课堂辨析","indices":[4]},{"title":"企业业务的兴起与转型","indices":[5]}]},{"q":1,"chapter":1,"section":"1.2","type":"单选","topic":"发展趋势","title":"计算机的发展趋势、分类与应用要分清依据","trigger":"题目要求辨析计算机体积、速度、功能与应用范围的发展趋势。","conclusion":"计算机总体向高性能、微型化、网络化、智能化等方向发展，体积增大不是速度提高的必要条件。","points":["集成度提高可以在更小体积内容纳更多器件并提升性能。","大型高性能计算机与微型设备会并行发展，不能用单一尺寸概括全部计算机。","性能取决于体系结构、芯片工艺、并行能力、存储与软件等多项因素。","巨型化侧重高性能、大容量与复杂计算能力，不是单纯把机箱做大。","按处理数据的形式，课堂区分模拟、数字和混合计算机：模拟量连续变化，数字量用离散数值表示，混合方式结合两者。按用途又分通用和专用。分类依据不同，普通个人电脑可同时属于数字计算机、通用计算机，不能把这两个名称当作互斥选项。","课堂按规模与功能性能区分巨型、大型、小型、微型计算机和工作站；普通个人电脑通常归为微型计算机，工作站侧重专业工作需要。这里比较的是系统能力与用途，不能只量机箱大小，也不能把“微型”理解为只能完成简单计算。","判断应用先看主要任务：科学计算侧重科学工程中的数值计算；信息管理侧重组织、存储、查询和处理业务数据，计算工资或平均分不会仅因用了算术就成为科学计算；过程控制侧重实时获取运行数据并及时调节。教学例子：发射前计算轨道属于科学计算，发射中根据偏差调整姿态体现过程控制。","课堂概括计算机的特点为运算速度快、计算精度高、存储能力强、能进行逻辑判断、可按程序自动处理和通用性强；这些特点不保证错误输入或错误程序也能得到正确结果。应用还包括计算机辅助、人工智能、网络通信、多媒体和嵌入式系统；按具体任务识别类别，不把应用名称当作另一套计算机代际。"],"boundary":"“计算能力更强”不能直接推导为“机器体积更大”。","id":"y2026q1","sources":[{"year":2026,"q":1,"type":"单选"},{"year":2022,"q":3,"type":"单选"}],"keys":["2026-1","2022-3"],"related":[{"id":"y2025q21","label":"电子管、晶体管与集成电路标志主要代际","reason":"集成电路的演进解释了设备为何可能更小且性能更强。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"比较性能应继续拆分字长、主频与核心数量，避免用外形或单一指标代替速度。"}],"pointPresentation":{"4":{"title":"计算机分类先看依据","navigationLabel":"计算机分类先看依据","blocks":[{"label":"按数据形式"},{"from":"按用途又分","label":"按用途"},{"from":"分类依据不同","label":"同一对象的多种身份"}]},"5":{"title":"规模性能分类与机箱大小","navigationLabel":"规模性能分类与机箱大小"},"6":{"title":"科学计算、信息管理与过程控制","navigationLabel":"科学计算、信息管理与过程控制","blocks":[{"label":"判断依据"},{"from":"教学例子","label":"同一情景的对照"}]},"7":{"title":"计算机特点与其他应用领域","navigationLabel":"计算机特点与其他应用领域","blocks":[{"label":"计算机特点"},{"from":"这些特点不保证","label":"能力限制"},{"from":"应用还包括","label":"其他应用领域"}]}},"pointGroups":[{"title":"发展趋势与性能","indices":[0,1,2,3]},{"title":"分类的不同依据","indices":[4,5]},{"title":"应用与能力边界","indices":[6,7]}]},{"q":41,"chapter":1,"section":"1.3","type":"填空","topic":"进制转换","title":"整数位权、小数分组与有限表示","trigger":"真题从十进制转十六进制、整数位权、二进制分组和小数精度考查进制转换。","conclusion":"任意进制转十进制用按位权展开；十进制整数转其他进制用除基取余、逆序排列，小数部分用乘基取整、顺序排列。","points":["r进制的个位权为r⁰，向左依次为r¹、r²，向右依次为r⁻¹、r⁻²；例如10001₂=16+1=17₁₀。","十进制整数不断除以目标基数，直到商为0，再把余数倒序写出。教学示例：60÷16商3余12，3÷16商0余3；余数倒序为3、12，12用C表示，所以60₁₀=3C₁₆。不能漏掉最后一次商为0时得到的余数。","小数部分不断乘以目标基数，每次取整数部分，余下小数继续乘。教学示例：0.625×2=1.25，取1、余0.25；0.25×2=0.5，取0、余0.5；0.5×2=1，取1、余0，至此停止。按取出顺序写成0.101₂，不能倒序。","二进制转八进制每3位一组，转十六进制每4位一组；以小数点为界，整数左端、小数右端补0。100010.01₂=0010 0010.0100₂=22.4₁₆，11.11₂=3.C₁₆。","有限十进制小数未必能用有限二进制精确表示；约分后分母为2的幂时才能有限表示，如0.5可以，0.1不可以。一般地，分母的质因数须全部包含在目标基数的质因数中。","r进制使用r种数码，数码取值从0到r−1；十六进制用A至F表示10至15。因此二进制不能出现2，八进制不能出现8或9。位权由基数和位置决定，与该位上写的是哪个数码无关；先检查数码合法，再按位权转换，不能把数码本身称为位权。","按位权展开，就是把每位数码乘以该位位权，再把各项相加。例如3C₁₆=3×16¹+12×16⁰=60₁₀；字母C是数码12，16¹和16⁰才是对应位置的位权。"],"boundary":"整数除基所得余数要逆序，小数乘基所得整数要顺序；不能跨小数点分组。3CH与0x3C都是十六进制记法，保留有限位数时还应按题设截断或舍入。","id":"y2026q41","sources":[{"year":2023,"q":41,"type":"填空"},{"year":2024,"q":31,"type":"判断"},{"year":2024,"q":42,"type":"填空"},{"year":2025,"q":41,"type":"填空"},{"year":2026,"q":41,"type":"填空"},{"year":2022,"q":42,"type":"填空"}],"keys":["2023-41","2024-31","2024-42","2025-41","2026-41","2022-42"],"related":[{"id":"y2020q31","label":"二进制减法与借位规则","reason":"将二进制减法结果转成十进制，可用位权展开进行交叉校验。"},{"id":"y2025q2","label":"字符编码、汉字机内码、字形与全角半角要分清","reason":"十六进制换算直接用于ASCII码值及大小写码值差的计算。"}],"pointGroups":[{"title":"合法数码与按位权求值","indices":[5,0,6]},{"title":"除基取余与乘基取整","indices":[1,2]},{"title":"二进制按组转换八、十六进制","indices":[3]},{"title":"什么时候能有限精确表示","indices":[4]}],"pointPresentation":{"0":{"title":"位权展开转十进制","navigationLabel":"位权展开转十进制"},"1":{"title":"整数除基取余，逆序排列","navigationLabel":"整数除基取余，逆序排列","blocks":[{"label":"方法"},{"from":"教学示例","label":"完整算例"},{"from":"不能漏掉","label":"检查"}]},"2":{"title":"小数乘基取整，顺序排列","navigationLabel":"小数乘基取整，顺序排列","blocks":[{"label":"方法"},{"from":"教学示例","label":"完整算例"},{"from":"按取出顺序","label":"结果"}]},"3":{"title":"二、八、十六进制分组与补零","navigationLabel":"二、八、十六进制分组与补零"},"4":{"title":"有限小数的表示条件","navigationLabel":"有限小数的表示条件"},"5":{"title":"数码、基数与位权的区别","navigationLabel":"数码、基数与位权的区别"},"6":{"title":"数码乘位权再求和","navigationLabel":"数码乘位权再求和"}}},{"q":31,"chapter":1,"section":"1.3","type":"填空","topic":"二进制运算","title":"二进制减法与借位规则","trigger":"题目要求计算二进制数1001减去111。","conclusion":"1001₂ − 111₂ = 10₂；前导0可以省略。","points":["二进制减法遵循“借一当二”：0减1时向高位借1，本位得到2。教学示例1001₂−0111₂：个位1−1=0；位权为2的这一位不够减1，左邻位的位权为4、数字也是0，须从位权为8的那一位借1，先换成两个4，再把其中一个4换成两个2。借位后，位权8、4、2、1各位暂记为0、1、2、1；再与0、1、1、1逐位相减，得到0010₂。中间的2是借位暂记，不能作为最终二进制数字。","可先转成十进制校验：9−7=2，再将2写成二进制10；也可反向检查10₂＋111₂=1001₂。","结果写成010或0010数值相同，但通常省略无意义的前导0；若题设要求固定四位表示，则保留0010。"],"boundary":"按位计算时要把两个数右对齐；前导0不改变数值，小数点后的尾随0也通常不改变数值。","id":"y2020q31","sources":[{"year":2020,"q":31,"type":"填空"}],"keys":["2020-31"],"related":[{"id":"y2026q41","label":"整数位权、小数分组与有限表示","reason":"借位中的“借一当二”来自二进制位权；进制转换也可校验减法结果。"}],"pointGroups":[{"title":"怎样连续借位","indices":[0]},{"title":"怎样校验和书写结果","indices":[1,2]}],"workedExamples":[{"year":2020,"q":31,"questionSummary":"计算一组二进制减法。","reasoning":["1001₂表示9，111₂表示7，所以差为2，可先用十进制复核。","右对齐为1001₂−0111₂；从右逐位相减，不够减时越过中间的0向高位连续借位，按“借一当二”计算。","结果写为10₂；若保留四位则为0010₂。前导零不改变数值。"],"pitfall":"把借来的高位1仍当成本位1，或把二进制数字当十进制字符串相减。","transfer":"换成多位连续0的被减数时，借位要向更高位逐级传递；算后用位权求值核对。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"本轮已核对原卷扫描题干及全部条件；配套答案未署名，不能据此称为官方答案","historicalVersionNote":""}],"pointPresentation":{"0":{"title":"连续借位的完整过程","navigationLabel":"连续借位的完整过程","blocks":[{"label":"规则"},{"from":"教学示例","label":"连续借位算例"},{"from":"中间的2","label":"结果的书写限制"}]},"1":{"title":"十进制与加法校验","navigationLabel":"十进制与加法校验"},"2":{"title":"前导零与固定位数","navigationLabel":"前导零与固定位数"}}},{"q":32,"chapter":1,"section":"1.3","type":"填空","topic":"信息表示","title":"bit、Byte、像素与存储容量单位","trigger":"三道题分别考查bit与Byte、容量换算以及数字图像的构成与存储。","conclusion":"bit表示一个二进制位，Byte表示字节，1 B=8 bit；容量计算先统一位与字节，再按题设选择1000或1024进位。","points":["SI前缀按1000进位：1 kB=1000 B，1 MB=10⁶ B，1 GB=10⁹ B，1 TB=10¹² B。","IEC前缀按1024进位：1 KiB=2¹⁰ B，1 MiB=2²⁰ B，1 GiB=2³⁰ B，1 TiB=2⁴⁰ B。","旧教材常用KB、MB表示1024进位。题目明确采用此口径时按题设计算，并在步骤中写清换算关系；跨两级需要乘或除两次进率。","像素是位图的基本图像元素。未压缩像素数据量=宽×高×每像素位数÷8，结果单位为B；24位RGB通常是红、绿、蓝各8位。","例如1024×768像素、每像素24位的图像，纯像素数据为2359296 B=2.25 MiB。bit/s是位速率，B/s是字节速率，同一前缀下数值相差8倍。","每像素用24位表示颜色时，最多可表示2²⁴种编码组合；计算像素数据量仍乘24位，再除以8换成字节。2²⁴回答“有多少种组合”，24回答“每像素占多少位”，两者不能相互代入容量公式。"],"boundary":"图像公式计算的是题设条件下的像素数据，不一定等于图像文件大小；文件头、调色板、行填充及压缩会改变文件大小。像素不能直接作为所有图形文件的存储单位。","id":"merged-3","sources":[{"year":2020,"q":32,"type":"填空"},{"year":2025,"q":22,"type":"多选"},{"year":2026,"q":2,"type":"单选"}],"keys":["2020-32","2025-22","2026-2"],"related":[{"id":"y2025q2","label":"字符编码、汉字机内码、字形与全角半角要分清","reason":"点阵字形容量同样按位数除以8计算，但不能拿它代替字符编码长度。"},{"id":"y2024q32","label":"采样、位深、编码与冗余共同决定数字媒体数据量","reason":"图像容量公式可推广到音频、视频；采样、位深与压缩会改变数据量。"},{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"下载速率常写bit/s，文件容量常写B，估算传输时间前必须统一两者。"}],"pointGroups":[{"title":"容量前缀怎样换算","indices":[0,1,2]},{"title":"图像数据与传输速率怎样算","indices":[3,4]},{"title":"课堂与真题的判断边界","indices":[5]}],"pointPresentation":{"0":{"title":"SI容量单位：1000进位","navigationLabel":"SI容量单位：1000进位"},"1":{"title":"IEC容量单位：1024进位","navigationLabel":"IEC容量单位：1024进位"},"2":{"title":"教材KB与题设口径","navigationLabel":"教材KB与题设口径"},"3":{"title":"未压缩像素数据公式","navigationLabel":"未压缩像素数据公式"},"4":{"title":"图像计算例与bit/s换算","navigationLabel":"图像计算例与bit/s换算"},"5":{"title":"颜色组合数与每像素位数","navigationLabel":"颜色组合数与每像素位数"}}},{"q":31,"chapter":1,"section":"1.3","type":"判断","topic":"字符编码","title":"字符编码、汉字机内码、字形与全角半角要分清","trigger":"真题从ASCII、汉字机内码规则、字形码和全角半角考查字符表示。","conclusion":"字符编码解决“这是哪个字符”，字形数据解决“这个字符怎样显示”；字符占用多少字节必须结合具体编码，不能笼统认定汉字永远占两个字节。","points":["标准ASCII为7位，共128个编码，存入一个8位字节时最高位通常为0；数字字符0至9、大写A至Z、小写a至z分别连续，按码值比较时数字字符小于大写字母、大写字母小于小写字母。这里比较的是字符编码，不是把字符当数值做大小比较。","ASCII中A=41H、a=61H，同一字母的大小写码值相差20H；G=47H，因此J=4AH。H表示十六进制，不参与数值运算。","区位码表示字符在编码表中的区和位，国标码用于信息交换，机内码用于内部表示；教材常见GB2312双字节汉字机内码两个字节最高位均为1，但满足此条件仍不能保证编码合法。","Unicode为字符分配码位，UTF-8和UTF-16规定具体编码形式；UTF-8编码一个Unicode标量值使用1至4字节，UTF-16使用2或4字节。全角Ａ与半角A也是不同字符，不能只看外形判断相同。","字形可用点阵或轮廓描述。单色、每点1位且不计附加信息时，16×16点阵字形占32 B，24×24占72 B；换字体可选用不同字形，改字号改变显示尺度，但字符身份不因此改变，也不能据此推断TXT文件或字体文件一定变大。","教学示例：A的码位为U+0041，中的码位为U+4E2D；按UTF-8编码，A为41，中为E4 B8 AD，所以字符串A中占4 B（不计BOM和换行）。同一文本换成另一种编码时字节可以变化；只改显示字体、字形或字号时，不会因此重写字符编码。","排查显示异常要先分层：出现不合语义的乱码时检查打开所用编码与保存编码是否一致；出现方框等缺字形提示时再检查字体及字体回退。全角Ａ（U+FF21）变成半角A（U+0041）则确实换了字符，不能与单纯换字体混为一谈。","输入码又称外码，方便人把汉字送入计算机，例如拼音输入码、五笔输入码；同一个汉字可有不同输入方案。输入码回答“怎样输入”，机内码回答“怎样在内部表示”，字形码回答“怎样显示或打印”，三者不能替换。","标准ASCII的128个编码不包含汉字。GB18030支持汉字；UTF-8、UTF-16、UTF-32均可表示Unicode中的汉字，其中UTF-32用一个32位码元表示一个Unicode标量值。判断“能否编码汉字”与计算“占多少字节”是两个问题，不能只凭编码名称中的数字作答。","ASCII空格的码值为32₁₀，即20H；它是字符，不是没有数据。标准ASCII用7位表示128个编码；8位共有256种组合，不能据此把标准ASCII的编码个数改为256。"],"boundary":"双字节机内码、16×16点阵和16位编码是不同概念。字符编码长度不能用点阵规模求，字形数据量也不能套用“一汉字两字节”。","id":"y2025q2","sources":[{"year":2023,"q":31,"type":"判断"},{"year":2024,"q":2,"type":"单选"},{"year":2025,"q":2,"type":"单选"},{"year":2022,"q":21,"type":"多选"},{"year":2021,"q":31,"type":"填空","page":5}],"keys":["2023-31","2024-2","2025-2","2022-21","2021-31"],"comparison":{"headers":["比较项","字符编码","字形数据"],"rows":[["回答的问题","表示哪个字符","这个字符怎样显示或打印"],["常见表示","ASCII、GB2312及Unicode的具体编码形式","点阵或轮廓"],["容量取决于","具体编码形式及字符","点阵规模、每点位数或轮廓描述"],["典型计算","标准ASCII通常存入1 B；GB2312汉字通常为2 B","16×16单色点阵：16×16÷8=32 B"],["字体或字号改变","字符身份与编码长度不因此改变","显示外观可以改变，字体文件未必被改写"]]},"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"计算16×16单色字形容量前，先掌握bit到Byte的换算。"},{"id":"y2026q41","label":"整数位权、小数分组与有限表示","reason":"ASCII的41H、61H是十六进制码值，比较和运算需要进制与位权知识。"},{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"Word全角半角转换改变字符本身，格式刷只改变外观，可检验编码与格式的区别。"}],"pointGroups":[{"title":"ASCII范围、空格与码值计算","indices":[0,9,1]},{"title":"汉字输入与内部编码","indices":[7,2]},{"title":"Unicode形式与实际字节","indices":[3,8,5]},{"title":"字形容量与显示异常","indices":[4,6]}],"pointPresentation":{"0":{"title":"ASCII范围与字符排序","navigationLabel":"ASCII范围与字符排序","blocks":[{"label":"范围与存储"},{"from":"数字字符0","label":"比较码值"},{"from":"这里比较的是","label":"判断边界"}]},"1":{"title":"ASCII大小写码值计算","navigationLabel":"ASCII大小写码值计算"},"2":{"title":"区位、国标与机内码","navigationLabel":"区位、国标与机内码"},"3":{"title":"Unicode码位与UTF编码形式","navigationLabel":"Unicode码位与UTF编码形式"},"4":{"title":"字形点阵与容量","navigationLabel":"字形点阵与容量","blocks":[{"label":"字形表示与容量"},{"from":"换字体可","label":"字体与字号的影响"}]},"5":{"title":"A中字符串的UTF-8字节","navigationLabel":"A中字符串的UTF-8字节"},"6":{"title":"乱码、缺字形与全角半角","navigationLabel":"乱码、缺字形与全角半角"},"7":{"title":"输入码解决怎样输入汉字","navigationLabel":"输入码解决怎样输入汉字"},"8":{"title":"哪些编码能够表示汉字","navigationLabel":"哪些编码能够表示汉字"},"9":{"title":"空格与标准ASCII的七位边界","navigationLabel":"空格与标准ASCII的七位边界"}}},{"q":21,"chapter":1,"section":"1.4","type":"多选","topic":"体系结构","title":"冯·诺依曼结构与存储程序原理","trigger":"真题从五大部件、控制器职责、二进制表示和存储程序思想反复考查经典计算机体系结构。","conclusion":"经典冯·诺依曼计算机由运算器、控制器、存储器、输入设备和输出设备组成；程序指令与数据均用二进制表示，并存放在同一存储体系中。","points":["基础组成题通常把运算器和控制器合称CPU；实际CPU还包含寄存器等部件。","运算器执行算术和逻辑运算；控制器取出指令、解释操作要求、发出控制信号并协调各部件。","“存储程序”强调先把程序指令存入存储器；“程序控制”强调机器按指令要求自动完成操作。","程序指令和数据都表现为二进制位串，不能仅看某个位串的外形判断它一定是指令或一定是数据，要结合访问与解释方式。","普通通用计算机通常把需要执行的代码从外存装入内存，由CPU反复取指、译码和执行；转移指令可以改变后续执行位置。","人物贡献题先区分对象：图灵研究可计算性并提出通用计算机器的理论模型；经典存储程序计算机的体系结构通常联系冯·诺依曼及其EDVAC报告。抽象计算模型、具体体系结构和ENIAC实物不是同一对象，不能只见到0和1就混同这些贡献，也不能将二进制本身的发明归给上述某一人。","完整的计算机系统由硬件系统和软件系统组成。硬件是实现计算、存储和输入输出等功能的物理部件；软件包括程序、数据及相关文档。这里的五大部件是硬件的功能划分，不能把它们当成计算机系统只有硬件、没有软件。"],"boundary":"五大部件是功能划分，不是五块独立芯片；存储程序不表示只能从第一条到最后一条直线执行，也不表示程序保存在硬盘上就已经运行。","id":"merged-1","sources":[{"year":2020,"q":21,"type":"多选"},{"year":2023,"q":42,"type":"填空"},{"year":2024,"q":22,"type":"多选"},{"year":2026,"q":22,"type":"多选"},{"year":2022,"q":1,"type":"单选"},{"year":2022,"q":31,"type":"判断"}],"keys":["2020-21","2023-42","2024-22","2026-22","2022-1","2022-31"],"related":[{"id":"y2024q41","label":"机器指令由操作码和地址码等部分组成","reason":"理解控制器取指译码后，再看操作码和操作数字段怎样规定执行内容。"},{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"程序从外存装入RAM再执行，把存储程序原理与运行内存的用途连接起来。"},{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"代码已存入磁盘还不等于运行；进程描述程序的一次实际执行。"}],"pointGroups":[{"title":"计算机系统、硬件与软件的关系","indices":[6]},{"title":"CPU部件各做什么","indices":[0,1]},{"title":"指令怎样存储并运行","indices":[2,3,4]},{"title":"人物贡献与体系结构","indices":[5]}],"workedExamples":[{"year":2020,"q":21,"questionSummary":"检查冯·诺依曼结构的组成与部件职责。","reasoning":["硬件通常按运算器、控制器、存储器、输入设备和输出设备五部分理解。","运算器处理算术和逻辑运算，控制器协调取指、译码和执行；数据和指令以二进制表示并存入存储器。","题面把运算交给控制器、把程序放进运算器，都是把部件职责写错。"],"pitfall":"只记五大部件名称，没有把“计算、指挥、保存”对应到正确对象。","transfer":"画出输入、存储、运算、输出之间的数据流，再单独标控制信号，避免把控制流和数据流混淆。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"本轮已核对原卷扫描题干及全部选项；配套答案未署名","historicalVersionNote":""}],"pointPresentation":{"0":{"title":"CPU与五大部件","navigationLabel":"CPU与五大部件"},"1":{"title":"运算器和控制器的分工","navigationLabel":"运算器和控制器的分工"},"2":{"title":"存储程序与程序控制","navigationLabel":"存储程序与程序控制"},"3":{"title":"二进制位串的解释身份","navigationLabel":"二进制位串的解释身份"},"4":{"title":"取指、译码、执行与转移","navigationLabel":"取指、译码、执行与转移"},"5":{"title":"图灵模型与冯·诺依曼体系结构","navigationLabel":"图灵模型与冯·诺依曼体系结构"},"6":{"title":"硬件与软件的系统关系","navigationLabel":"硬件与软件的系统关系"}}},{"q":2,"chapter":1,"section":"1.4","type":"单选","topic":"计算机指令","title":"机器指令由操作码和地址码等部分组成","trigger":"真题从机器能否直接执行、操作码含义和地址信息考查指令结构。","conclusion":"机器指令是CPU可直接识别执行的操作命令，基础模型通常概括为操作码与地址码等部分；具体字段和含义由指令系统规定。","points":["操作码说明执行什么操作，如加法、传送或转移；地址码等字段提供操作数及结果位置等相关信息。","操作数可能来自寄存器、存储器，也可能是指令中直接给出的立即数，因此不能把每个操作数字段都理解成主存地址。","一条指令规定一次机器操作；程序是为完成任务组织起来的指令序列，可能包含顺序、分支和循环。","一台处理器能够识别的全部机器指令构成其指令系统；不同处理器架构的机器代码不保证能够直接互用。","机器指令可以直接执行；汇编源程序需汇编，高级语言源程序通常需编译、解释或其他语言处理过程。"],"boundary":"不要把“源程序需要翻译”扩大为“任何指令都要先编译”；也不要认为每条指令必须显式给出主存地址或下一条指令地址。","id":"y2024q41","sources":[{"year":2023,"q":2,"type":"单选"},{"year":2024,"q":41,"type":"填空"}],"keys":["2023-2","2024-41"],"related":[{"id":"merged-1","label":"冯·诺依曼结构与存储程序原理","reason":"取指、译码、执行依赖控制器与存储器协同，指令字段必须放回这个过程理解。"},{"id":"y2020q23","label":"机器语言、汇编语言与高级语言","reason":"区分机器指令可直接执行与汇编、高级语言源程序需要语言处理。"},{"id":"y2022q4","label":"数据、地址、控制总线各司其职","reason":"地址码描述指令中的信息，地址总线传递访问位置，二者不是同一硬件对象。"}],"pointGroups":[{"title":"指令字段怎样表达操作与操作数","indices":[0,1]},{"title":"指令、程序与语言处理的关系","indices":[2,3,4]}],"pointPresentation":{"0":{"title":"操作码与操作数字段","navigationLabel":"操作码与操作数字段"},"1":{"title":"立即数、寄存器和存储地址","navigationLabel":"立即数、寄存器和存储地址"},"2":{"title":"一条指令与完整程序","navigationLabel":"一条指令与完整程序"},"3":{"title":"指令系统与架构差异","navigationLabel":"指令系统与架构差异"},"4":{"title":"机器指令与源程序","navigationLabel":"机器指令与源程序"}}},{"q":23,"chapter":1,"section":"1.4","type":"多选","topic":"程序语言","title":"机器语言、汇编语言与高级语言","trigger":"题目要求从机器语言、汇编语言、C和C++中识别高级语言。","conclusion":"C和C++属于高级程序设计语言；机器语言和汇编语言属于低级语言。","points":["机器语言由机器指令代码构成，可由CPU直接识别执行。","汇编语言用助记符表达机器指令，需要汇编程序翻译。","高级语言更接近人的表达，通常通过编译、解释或混合方式运行。","教学示例：用记事本写出的C源文件仍是文本。采用常见本地编译流程时，编译器先把源代码翻译为目标代码，链接器再结合所需代码和库生成可执行文件；双击源文件通常只是按文件关联打开编辑器，不会自动把它变成可执行程序。","基础题中的典型编译过程先把源程序翻译为目标程序，再经过所需处理运行；典型解释过程边分析、翻译边执行，不先生成供随后独立执行的目标程序。编辑源文件是在修改文本，编译是在做语言翻译。实际系统可使用中间代码或混合方式，不能推成“解释绝不产生任何中间结果”，也不能只凭语言级别断定所有程序的运行快慢。"],"boundary":"“高级语言”不代表计算机可以直接执行；源程序仍需经过语言处理系统。","id":"y2020q23","sources":[{"year":2020,"q":23,"type":"多选"},{"year":2022,"q":2,"type":"单选"}],"keys":["2020-23","2022-2"],"related":[{"id":"y2024q41","label":"机器指令由操作码和地址码等部分组成","reason":"CPU直接执行的是机器指令，可用指令字段理解机器语言与源程序的区别。"}],"pointGroups":[{"title":"三种语言的表达与执行方式","indices":[0,1,2]},{"title":"编译与解释的典型过程","indices":[4]},{"title":"源文件怎样成为可执行程序","indices":[3]}],"pointPresentation":{"0":{"title":"机器语言直接执行","navigationLabel":"机器语言直接执行"},"1":{"title":"汇编语言与汇编程序","navigationLabel":"汇编语言与汇编程序"},"2":{"title":"高级语言的运行方式","navigationLabel":"高级语言的运行方式"},"3":{"title":"源文件、目标代码与可执行文件","navigationLabel":"源文件、目标代码与可执行文件"},"4":{"title":"编译与解释的典型流程","navigationLabel":"编译与解释的典型流程","blocks":[{"label":"典型流程"},{"from":"编辑源文件","label":"编辑与翻译"},{"from":"实际系统可","label":"实现边界"}]}}},{"q":33,"chapter":1,"section":"1.4","type":"填空","topic":"软件分类","title":"系统软件与应用软件按功能区分","trigger":"真题从软件定义、操作系统、系统自带程序和日常App反复考查软件分类。","conclusion":"软件包括程序、数据及相关文档；操作系统属于系统软件，微信、支付宝等直接服务具体任务的程序属于应用软件。","points":["系统软件管理硬件资源并为应用提供运行环境。","办公软件、通信支付App、图形工具和业务系统通常属于应用软件。","某程序随操作系统附带，不代表它必然属于系统软件。","Linux、DOS属于操作系统；Photoshop和WPS主要完成用户的具体工作，属于应用软件。","课堂把操作系统、语言处理程序、支撑服务程序和数据库管理系统列为系统软件：分别侧重资源管理、程序翻译、系统维护支持和数据库管理。数据库管理系统与使用数据库完成挂号、收费等业务的应用程序不是同一层。裸机指未配置任何软件的硬件系统；已装操作系统就不再是裸机。"],"boundary":"“系统自带”“预装”和“系统软件”不是同义词，分类应看主要功能。","version":"按Windows 10现行口径整理","id":"merged-2","sources":[{"year":2020,"q":33,"type":"填空"},{"year":2023,"q":22,"type":"多选"},{"year":2025,"q":3,"type":"单选"},{"year":2026,"q":21,"type":"多选"},{"year":2021,"q":22,"type":"多选","page":4}],"keys":["2020-33","2023-22","2025-3","2026-21","2021-22"],"related":[{"id":"y2024q6","label":"实时、分布式与通用操作系统按目标区分","reason":"操作系统以资源管理、调度和安全为目标，具体说明它为何属于系统软件。"},{"id":"y2025q34","label":"Windows附件各有功能边界","reason":"记事本、画图虽随Windows提供，仍要按其完成的用户任务判断功能类别。"}],"pointPresentation":{"0":{"title":"系统软件的职责","navigationLabel":"系统软件的职责"},"1":{"title":"应用软件的职责","navigationLabel":"应用软件的职责"},"2":{"title":"系统附带不等于系统软件","navigationLabel":"系统附带不等于系统软件"},"3":{"title":"操作系统与应用实例","navigationLabel":"操作系统与应用实例"},"4":{"title":"系统软件的类别与裸机","navigationLabel":"系统软件的类别与裸机","blocks":[{"label":"系统软件分类"},{"from":"数据库管理系统与","label":"业务应用的区别"},{"from":"裸机指","label":"裸机的条件"}]}},"pointGroups":[{"title":"软件的功能分类","indices":[0,1,2,3]},{"title":"系统软件类别与配置","indices":[4]}]},{"q":1,"chapter":1,"section":"1.4","type":"单选","topic":"存储器","title":"RAM与ROM的断电特性","trigger":"真题用断电场景反复考查RAM与ROM的易失性。","conclusion":"普通RAM是可读写的运行内存，断电后内容丢失；ROM常用于保存固件，具有非易失性。读写特性、断电特性和主存外存是不同分类维度。","points":["RAM暂存正在运行的程序和数据；程序或文件保存在磁盘上，不代表其全部内容一直位于RAM中。","DRAM需要定期刷新，常用作主存；SRAM不需要这种刷新，常用作Cache。两者在普通实现中都需要持续供电保存内容。","Cache是高速缓冲存储器，用于减少CPU访问较慢主存的等待；它不是硬盘，也不是另一种永久文件保存位置。","ROM常保存固件或启动代码；EEPROM等类型可按规定方式擦写，不能把所有ROM都理解成出厂后永远无法改变。","SSD、U盘使用的Flash具有非易失性，但这些设备通常归为外存；HDD同样能断电保存数据，因此非易失存储器不等于ROM。","普通剪贴板在内存中暂存复制或剪切的数据；回收站主要在磁盘上暂存符合条件的已删除文件，二者不能混为一谈。Windows剪贴板历史记录另有固定、同步等功能，不能把普通剪贴板的断电口径无条件套用于所有历史记录。","典型存储层次为CPU内的寄存器、Cache、主存RAM，再到外存。越靠近CPU，通常速度越快、容量越小、单位容量成本越高；这是典型层次关系，不是所有具体设备的速度排名。CPU是处理器，包含寄存器，不能把整个CPU当成一种存储器与Cache并列比较。"],"boundary":"RAM中的“随机访问”不等于“随机存入”，也不应据名称推导所有RAM技术都易失；基础题未作特殊说明时，通常讨论普通易失性RAM。断电能否保留、能否改写、属于主存还是外存，要分别判断。","id":"y2026q3","sources":[{"year":2024,"q":1,"type":"单选"},{"year":2026,"q":3,"type":"单选"},{"year":2021,"q":21,"type":"多选","page":4}],"keys":["2024-1","2026-3","2021-21"],"comparison":{"headers":["名称","分类关系与典型用途","普通实现的断电特性","刷新或改写"],"rows":[["RAM","随机存取存储器；基础题通常指运行内存","普通RAM易失","可读写；是否刷新取决于类型"],["SRAM","RAM的一类；常用于Cache","易失","无需DRAM式定期刷新"],["DRAM","RAM的一类；常用于主存","易失","需要定期刷新"],["ROM","只读存储器家族；常保存固件","非易失","能否改写及方式取决于具体类型"],["Flash","闪存；常用于SSD、U盘及固件存储","非易失","可按规定方式电擦除、编程"]]},"related":[{"id":"y2025q31","label":"固态硬盘通常比机械硬盘读写更快","reason":"SSD也能断电保存数据，但通常归外存，可排除“非易失就等于ROM”的误判。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"剪贴板暂存数据及历史记录的规则，要结合运行内存与持久保存的区别。"},{"id":"y2026q32","label":"长按电源键是强制断电手段","reason":"普通RAM断电丢失解释了强制关机为何会丢失未保存内容。"}],"pointGroups":[{"title":"运行内存与Cache","indices":[0,1,2]},{"title":"ROM、Flash与外存分类","indices":[3,4]},{"title":"寄存器、Cache、主存与外存的层次","indices":[6]},{"title":"剪贴板和回收站存在哪里","indices":[5]}],"pointPresentation":{"0":{"title":"RAM中的程序和数据","navigationLabel":"RAM中的程序和数据"},"1":{"title":"DRAM刷新与SRAM","navigationLabel":"DRAM刷新与SRAM"},"2":{"title":"Cache减少等待","navigationLabel":"Cache减少等待"},"3":{"title":"ROM与可擦写类型","navigationLabel":"ROM与可擦写类型"},"4":{"title":"非易失性不等于ROM","navigationLabel":"非易失性不等于ROM"},"5":{"title":"普通剪贴板与磁盘回收站","navigationLabel":"普通剪贴板与磁盘回收站","blocks":[{"label":"存储位置"},{"from":"Windows剪贴板历史","label":"适用边界"}]},"6":{"title":"寄存器、Cache、主存与外存的层次","navigationLabel":"寄存器、Cache、主存与外存的层次","blocks":[{"label":"典型层次"},{"from":"越靠近CPU","label":"典型比较与限制"},{"from":"CPU是处理器","label":"图示对象辨析"}]}}},{"q":31,"chapter":1,"section":"1.4","type":"判断","topic":"CPU与GPU","title":"GPU擅长并行计算但不能全面替代CPU","trigger":"题目判断图形处理器能否完全替代中央处理器。","conclusion":"GPU适合大量相似任务的并行运算，CPU更擅长通用控制、复杂分支和系统协调，两者通常协同工作。","points":["CPU拥有完善的控制逻辑和通用指令执行能力。","GPU通过大量计算单元提高图形和矩阵等并行任务吞吐量。","人工智能训练常依赖GPU加速，但操作系统和通用程序仍需要CPU。"],"boundary":"某些专用设备可弱化传统CPU角色，但不能据此说GPU在通用计算机中已经完全替代CPU。","id":"y2026q31","sources":[{"year":2026,"q":31,"type":"判断"}],"keys":["2026-31"],"related":[{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"多计算单元只有遇到可并行任务才带来收益，不能简单把数量相加成主频。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"算力需要结合任务类型理解，GPU的矩阵吞吐量不代表所有通用任务都更快。"}]},{"q":1,"chapter":1,"section":"1.5","type":"单选","topic":"硬件识别","title":"从外形识别内存条","trigger":"题目通过硬件实物图考查CPU、内存、网卡和主板的区分。","conclusion":"图中长条形电路板、成排金手指和多颗存储芯片是内存条的典型特征。","points":["内存条安装在主板内存插槽中，承担主存储器的主要RAM功能。","CPU通常是带顶盖的方形芯片；主板是承载插槽、接口和芯片的大型电路板；网卡通常带网络接口。","识图时先看连接形式和用途，不依赖品牌标签。","微型计算机以微处理器为核心，常见整机形态包括台式机、笔记本和平板，笔记本和平板突出便携需求。这里按形态区分，与数字或模拟、通用或专用等分类依据不同；用于日常办公的笔记本，可以同时属于数字计算机、通用计算机和微型计算机。先识别整机形态，再辨认其中承担处理、存储和输入输出的部件，不能把“微型”当成低性能的同义词。"],"boundary":"内存条属于主存硬件，不等同于SSD、U盘等外存；“内存”和“存储空间”在日常表达中也不能混用。","id":"y2020q1","sources":[{"year":2020,"q":1,"type":"单选"}],"keys":["2020-1"],"related":[{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"识别内存条后，再用RAM的用途和断电特性确认它与外存的区别。"},{"id":"y2020q22","label":"输入、输出与存储设备的判断","reason":"硬件识图还要按输入、输出和存储功能分类，不能只凭电路板外形判断。"}],"pointPresentation":{"3":{"title":"微型计算机的常见整机形态","navigationLabel":"微型计算机的常见整机形态"}},"pointGroups":[{"title":"微型计算机的常见形态","indices":[3]},{"title":"从外形与用途识别硬件","indices":[0,1,2]}]},{"q":22,"chapter":1,"section":"1.5","type":"多选","topic":"输入设备","title":"输入、输出与存储设备的判断","trigger":"题目要求判断手写板、麦克风、投影仪和硬盘中哪些能够向计算机输入信息。","conclusion":"手写板和麦克风是典型输入设备；投影仪是输出设备；硬盘是外存，也承担双向读写。","points":["输入设备把外界信息转换成计算机可处理的数据。","输出设备把处理结果转换为人或其他设备可接收的形式。","硬盘读出数据时有输入方向、写入时有输出方向，但规范分类通常称为外存储器或输入输出设备。","触摸屏同时承担显示输出和触摸输入；扫描仪输入、音箱输出。U盘属于外部存储，读写会发生输入/输出传输，但不应简单归为仅输出设备。","题目问设备的规范分类时，硬盘、U盘属于外部存储或输入输出设备；若问“可作为输入设备”，读出已存数据有输入方向，问“可作为输出设备”，写入处理结果有输出方向。先看题干是按用途分类还是问传输方向，不能把双向存储设备改称仅输入或仅输出设备。"],"boundary":"“有数据进入计算机”不等于教材分类中一定叫纯输入设备；磁盘、网卡和触摸屏都具有双向性。","id":"y2020q22","sources":[{"year":2020,"q":22,"type":"多选"},{"year":2022,"q":22,"type":"多选"}],"keys":["2020-22","2022-22"],"related":[{"id":"merged-1","label":"冯·诺依曼结构与存储程序原理","reason":"五大部件按功能划分，触摸屏和存储设备的双向性要放在这一框架下判断。"},{"id":"y2020q1","label":"从外形识别内存条","reason":"内存条承担主存RAM功能，与硬盘、U盘这些外存设备分开识别。"}],"pointPresentation":{"0":{"title":"输入设备的任务","navigationLabel":"输入设备的任务"},"1":{"title":"输出设备的任务","navigationLabel":"输出设备的任务"},"2":{"title":"硬盘分类与读写方向","navigationLabel":"硬盘分类与读写方向"},"3":{"title":"触摸屏、扫描仪、音箱和U盘","navigationLabel":"触摸屏、扫描仪、音箱和U盘"},"4":{"title":"规范分类与“可作为”的题面条件","navigationLabel":"规范分类与“可作为”的题面条件"}},"pointGroups":[{"title":"设备功能与传输方向","indices":[0,1,2,3]},{"title":"题目条件怎样判断","indices":[4]}]},{"q":4,"target":null,"chapter":1,"section":"1.5","topic":"总线","title":"数据、地址、控制总线各司其职","conclusion":"数据总线传送内容，地址总线指定位置，控制总线传送读写等控制信号；地址宽度与数据宽度回答的是不同问题。","points":["数据总线传送指令、操作数和结果等信息；经典系统中读写需要不同传送方向。","地址总线指定要访问的存储单元或I/O位置；经典CPU作为总线主设备时，地址由CPU送出。","控制总线包含读、写、中断等信号；整组信号有不同方向，不表示每根控制线都能双向传送。","n位地址最多区分2ⁿ个地址。若按字节寻址，容量为2ⁿ B；例如20位地址可区分2²⁰个字节地址，即1 MiB。","m位并行数据总线一次可传送m位数据；地址线数不能代替数据线数。总线还可按传输方式分为串行与并行，这与按内容分类是不同维度。"],"boundary":"算可寻址容量必须先看一个地址对应多少存储量；2ⁿ首先是地址数，只有按字节寻址才能直接写成2ⁿ B。总线更宽也不能单独证明整机一定更快。","type":"单选","trigger":"从总线的判断与应用整理。","id":"y2022q4","sources":[{"year":2022,"q":4,"type":"单选"},{"year":2021,"q":32,"type":"填空","page":5}],"keys":["2022-4","2021-32"],"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"由地址数换算存储容量时，必须先确认按字节寻址，再进行B与MiB换算。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"地址线宽度、数据线宽度与机器字长回答不同问题，不能直接画等号。"},{"id":"merged-1","label":"冯·诺依曼结构与存储程序原理","reason":"总线把CPU、存储器和输入输出部件连接起来，可用五大部件定位各类传输。"}],"pointGroups":[{"title":"数据、地址和控制信号的分工","indices":[0,1,2]},{"title":"按线宽计算容量与传输位数","indices":[3,4]}],"pointPresentation":{"0":{"title":"数据总线传送内容","navigationLabel":"数据总线传送内容"},"1":{"title":"地址总线指定位置","navigationLabel":"地址总线指定位置"},"2":{"title":"控制信号的方向","navigationLabel":"控制信号的方向"},"3":{"title":"地址宽度与寻址容量","navigationLabel":"地址宽度与寻址容量"},"4":{"title":"数据宽度与传输方式","navigationLabel":"数据宽度与传输方式"}}},{"q":21,"chapter":1,"section":"1.5","type":"多选","topic":"性能指标","title":"字长、主频、核心与指令速度是不同性能指标","trigger":"真题从GHz、核心数量和处理速度等指标考查计算机性能。","conclusion":"字长描述典型处理位宽，主频描述每秒时钟周期数，核心数量描述并行执行资源；三者都不能单独代表整机实际速度。","points":["字长是处理器一次处理数据的典型二进制位数；基础题中的64位计算机通常指机器字长为64位，不是64字节。","1 GHz=10⁹ Hz，表示每秒10⁹个时钟周期；3.2 GHz表示每秒32亿个周期，不表示每秒必然执行32亿条指令。","MIPS表示每秒百万条指令，BIPS表示每秒十亿条指令；它们是指令执行速率单位，与表示容量的MB、GB不同。","多个核心可以同时处理任务，但必须有可并行的程序和合适的调度；四核3 GHz不能相加写成12 GHz。","同样主频下，不同体系结构、缓存和每周期处理能力可能带来不同速度；内存、存储设备和软件负载也会影响实际运行时间。","内存容量说明可容纳多少数据，常用B及其容量单位表示；存取周期说明连续启动两次独立读或写操作所需的最小时间间隔，属于时间指标。同类条件下周期短有利于更快存取，但不能把“容量大”“存取快”和“主频高”当成同一指标。"],"boundary":"字长、地址总线宽度和数据总线宽度不能直接视为相同；比较不同处理器时，不能只凭主频或MIPS大小作结论。","id":"y2025q1","sources":[{"year":2023,"q":21,"type":"多选"},{"year":2025,"q":1,"type":"单选"},{"year":2022,"q":32,"type":"判断"},{"year":2022,"q":41,"type":"填空"},{"year":2021,"q":2,"type":"单选","page":1}],"keys":["2023-21","2025-1","2022-32","2022-41","2021-2"],"comparison":{"headers":["指标","含义","常见误读"],"rows":[["字长","典型一次处理的二进制位数","64位不是64字节，也不等于地址线必有64根"],["主频","每秒时钟周期数；单位Hz、GHz","时钟周期数不是指令条数"],["核心数量","可并行工作的处理核心数量","四核3 GHz不能相加为12 GHz"],["MIPS、BIPS","每秒百万条、十亿条指令","不是MB、GB等存储容量单位"],["实际任务耗时","指定程序与环境下完成任务的时间","不能只由某一个硬件数字确定"]]},"related":[{"id":"y2022q4","label":"数据、地址、控制总线各司其职","reason":"字长与地址、数据总线宽度经常混淆，需分别判断处理位宽、寻址范围和传输位宽。"},{"id":"y2026q31","label":"GPU擅长并行计算但不能全面替代CPU","reason":"多核和GPU的速度收益都取决于任务能否并行，不能仅比较计算单元数量。"},{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"Cache与主存访问等待会影响运行时间，解释同主频设备为何仍有速度差异。"}],"pointGroups":[{"title":"字长、主频与指令速率的单位","indices":[0,1,2]},{"title":"内存容量与存取周期","indices":[5]},{"title":"并行条件与实际运行速度","indices":[3,4]}],"pointPresentation":{"0":{"title":"字长按位计算","navigationLabel":"字长按位计算"},"1":{"title":"主频是时钟周期数","navigationLabel":"主频是时钟周期数"},"2":{"title":"MIPS与BIPS","navigationLabel":"MIPS与BIPS"},"3":{"title":"多核主频不能相加","navigationLabel":"多核主频不能相加"},"4":{"title":"整机速度取决于负载与多项条件","navigationLabel":"整机速度取决于负载与多项条件"},"5":{"title":"内存容量与存取周期","navigationLabel":"内存容量与存取周期"}}},{"q":31,"chapter":1,"section":"1.5","type":"判断","topic":"固态硬盘","title":"固态硬盘通常比机械硬盘读写更快","trigger":"题目比较SSD与传统机械硬盘的读写速度。","conclusion":"SSD使用闪存等电子存储介质，没有机械寻道过程，随机读写和访问延迟通常优于HDD。","points":["HDD依靠盘片旋转和磁头寻道。","SSD抗震、静音、低延迟，但价格、寿命和数据恢复特性不同。","顺序速度和实际体验还受接口、控制器与负载影响。"],"boundary":"“通常更快”不等于任何SSD在所有任务中都必然快于任何HDD。","id":"y2025q31","sources":[{"year":2025,"q":31,"type":"判断"}],"keys":["2025-31"],"related":[{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"SSD和HDD都是可断电保存数据的外存，不应与RAM或ROM分类混淆。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"存储延迟会影响整机体验，CPU主频不能独自决定程序运行速度。"}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
