window.NOTE_DEMOS={"y2025q23":{"kind":"explore","title":"把数据送进解释器","task":"点击同一个“80”，观察语境如何把数据变成信息。","initial":"孤立的80只是符号化数据。","actions":[{"label":"80","stage":"数据","result":"只有符号，还不知道它描述什么。","tone":"warn"},{"label":"体重80千克","stage":"信息","result":"对象、数值和单位共同形成可理解含义。","tone":"good"},{"label":"考试成绩80分","stage":"另一条信息","result":"同一数据在不同语境中传递不同意义。","tone":"good"}]},"y2026q18":{"kind":"explore","title":"拆开“自主可控”","task":"点击四个环节，观察为什么只看“国产”两个字不够。","initial":"一套数据库能否长期自主运行，要看完整能力链。","actions":[{"label":"核心技术","stage":"核心代码与关键技术","result":"能理解、修改并持续演进关键技术，才不会被单点卡住。","tone":"good"},{"label":"知识产权","stage":"权利边界清晰","result":"合法拥有或获得充分授权，才能稳定使用、开发和分发。","tone":"good"},{"label":"供应链","stage":"关键环节可替代","result":"芯片、系统、数据库和工具链中，薄弱的一环就可能影响整体。","tone":"warn"},{"label":"维护生态","stage":"升级与迁移能力","result":"没有人才、文档、兼容和服务生态，产品也难以长期可控。","tone":"warn"}]},"y2025q21":{"kind":"explore","title":"检查ENIAC机房","task":"点击机房部件与程序设置，判断它属于哪一代、怎样工作。","initial":"ENIAC是早期第一代电子数字计算机。","actions":[{"label":"电子管机柜","stage":"第一代主要元件","result":"体积大、功耗高、发热明显。","tone":"good"},{"label":"十进制计数单元","stage":"不是典型二进制运算基础","result":"考试不要把后来的通用结构倒套给ENIAC。","tone":"warn"},{"label":"插线板与开关","stage":"最初不是存储程序方式","result":"更换任务需要人工重新接线和设置。","tone":"good"},{"label":"“已经采用存储程序”","stage":"错误","result":"存储程序思想在后续计算机中成为核心。","tone":"bad"}]},"y2026q1":{"kind":"choose","title":"识别错误的发展趋势","task":"考试给出若干趋势描述，点选后观察判断依据。","options":[{"label":"体积越大，速度越快","result":"错误。性能由工艺、体系结构、并行能力、存储等共同决定，体积不是必要条件。","tone":"bad"},{"label":"高性能与微型化并行发展","result":"正确。超级计算机追求规模，终端设备同时追求小型化和低功耗。","tone":"good"},{"label":"网络化、智能化不断增强","result":"正确。这是教材常见的计算机发展趋势概括。","tone":"good"}]},"y2024q41":{"kind":"explore","title":"把机器指令送进译码器","task":"点击指令的不同字段，观察控制器分别获得什么信息。","initial":"示例指令：ADD R1, [2048]。","actions":[{"label":"ADD","stage":"操作码","result":"告诉控制器执行加法。","tone":"good"},{"label":"R1","stage":"寄存器操作数","result":"指出一个数据位置。","tone":"good"},{"label":"2048","stage":"存储器地址","result":"指出另一个操作数的位置。","tone":"good"},{"label":"把地址当操作码","stage":"字段职责混淆","result":"地址回答“在哪里”，操作码回答“做什么”。","tone":"bad"}]},"y2020q23":{"kind":"explore","title":"看翻译层级辨语言","task":"点击三类语言，观察它们与CPU之间隔了什么。","initial":"越接近人类表达，通常越需要语言处理程序完成转换。","actions":[{"label":"机器语言","stage":"0101… → CPU","result":"由机器指令代码构成，可被CPU直接识别。","tone":"good"},{"label":"汇编语言","stage":"助记符 → 汇编器 → 机器指令","result":"用MOV等助记符表达，仍与机器结构关系紧密。","tone":"warn"},{"label":"高级语言","stage":"C/C++ → 编译或解释 → 机器执行","result":"更接近人的表达，但不能未经处理直接由CPU执行。","tone":"good"}]},"merged-2":{"kind":"explore","title":"把软件放进正确抽屉","task":"点击软件名称，观察分类依据是“主要功能”而不是“从哪里安装”。","initial":"系统软件提供运行环境；应用软件完成用户的具体任务。","actions":[{"label":"Windows 10","stage":"系统软件","result":"管理硬件、进程、文件并提供应用运行环境。","tone":"good"},{"label":"画图","stage":"应用软件","result":"虽然系统自带，但主要服务于绘图任务。","tone":"warn"},{"label":"Word 2016","stage":"应用软件","result":"直接完成文字处理任务。","tone":"good"},{"label":"语言处理程序","stage":"系统软件","result":"编译器、解释器通常归入系统软件。","tone":"good"}]},"y2026q31":{"kind":"explore","title":"把任务拖给合适的处理器","task":"用鼠标或手指把工作负载拖到CPU或GPU；放错会退回队列。","initial":"CPU和GPU分工协作，不是简单的替代关系。","actions":[{"label":"复杂分支与系统调度","stage":"CPU主导","result":"少量强核心与复杂控制逻辑更适合通用控制。","tone":"good"},{"label":"大规模矩阵并行","stage":"GPU加速","result":"大量相似计算可由众多计算单元并行完成。","tone":"good"},{"label":"运行整个操作系统","stage":"CPU主导，GPU协同","result":"GPU不具备全面替代通用CPU的条件。","tone":"warn"}]},"y2020q1":{"kind":"choose","title":"凭外形找出内存条","task":"题目常给硬件图片。点击最有辨识度的外形特征。","options":[{"label":"长条电路板＋成排金手指","result":"这是内存条的典型外形，安装在主板内存插槽中。","tone":"good"},{"label":"方形金属顶盖","result":"更像CPU封装，不是内存条。","tone":"bad"},{"label":"带RJ45网络接口","result":"更像网卡。","tone":"bad"},{"label":"布满插槽的大型电路板","result":"更像主板。","tone":"bad"}]},"y2020q22":{"kind":"explore","title":"沿数据方向判断设备","task":"点击设备，观察信息是进入、离开还是双向流动。","initial":"设备分类看主要功能，也要警惕磁盘等双向设备。","actions":[{"label":"手写板","stage":"人 → 计算机","result":"采集书写轨迹，属于输入设备。","tone":"good"},{"label":"麦克风","stage":"声音 → 计算机","result":"把声音转换为可处理的数据，属于输入设备。","tone":"good"},{"label":"投影仪","stage":"计算机 → 画面","result":"把结果呈现给人，属于输出设备。","tone":"good"},{"label":"硬盘","stage":"读取 ↔ 写入","result":"规范分类为外存，也具有输入输出双向性。","tone":"warn"}]},"y2025q1":{"kind":"explore","title":"调节CPU频率仪表","task":"点击参数，观察“3.20 GHz”真正描述什么。","initial":"CPU时钟：3.20 GHz。","actions":[{"label":"3.20 GHz","stage":"每秒约32亿个时钟周期","result":"这是频率，不是容量。","tone":"good"},{"label":"16 GB","stage":"内存容量","result":"GB用于计量存储容量。","tone":"warn"},{"label":"1 TB","stage":"硬盘容量","result":"不能把TB当作处理器速度。","tone":"warn"},{"label":"只看主频选最快CPU","stage":"证据不足","result":"架构、核心、缓存和负载同样重要。","tone":"bad"}]},"y2025q31":{"kind":"explore","title":"让SSD与HDD跑同一组任务","task":"点击工作负载，比较机械寻道和电子访问的差异。","initial":"两块盘都保存同一份文件。","actions":[{"label":"随机打开1000个小文件","stage":"SSD明显更快","result":"电子访问没有磁头寻道等待。","tone":"good"},{"label":"连续读取大文件","stage":"SSD通常更快","result":"实际速度还受接口和控制器限制。","tone":"good"},{"label":"受到剧烈震动","stage":"SSD更耐受","result":"HDD的机械结构更怕碰撞。","tone":"good"},{"label":"任何SSD都快于任何HDD","stage":"过度绝对","result":"设备等级与具体任务仍会影响结果。","tone":"bad"}]}};
